"""Tests for src/transcripts/source_reliability.py — the reliability ranking
that backs the ingest-time period-conflict guard."""

from __future__ import annotations

from pathlib import Path

from transcripts.source_reliability import (
    IR_TRANSCRIPT_DOC,
    MANUAL_PDF,
    UNKNOWN_LEGACY,
    choose_winner,
    classify_transcript_source,
    qa_availability_rank,
    reliability_rank,
    transcript_winner_key,
)


def _synth_text(source_name: str) -> str:
    return (
        "=== SYNTHESIZED QUARTERLY UPDATE — Q&A SEGMENT ONLY ===\n"
        "Generated by execution/fetch_qa_transcript.py from a free aggregator.\n"
        "\n"
        "Ticker:    NVDA\n"
        "Period:    Q1 2026\n"
        f"Source:    aggregator_{source_name} (https://example.com/x)\n"
        "\n"
        "=== Q&A SEGMENT ===\n"
        "Operator: first question...\n"
    )


def test_classify_ir_transcript_doc_type_wins_regardless_of_content() -> None:
    assert (
        classify_transcript_source(
            Path("whatever.pdf"), "no banner here", is_ir_transcript_doc=True
        )
        == IR_TRANSCRIPT_DOC
    )


def test_classify_reads_banner_source_line() -> None:
    assert (
        classify_transcript_source(Path("transcripts/raw/NVDA_Q1_2026.txt"), _synth_text("roic"))
        == "aggregator_roic"
    )
    assert (
        classify_transcript_source(
            Path("transcripts/raw/NVDA_Q1_2026.txt"), _synth_text("issuer_ir")
        )
        == "aggregator_issuer_ir"
    )
    assert (
        classify_transcript_source(
            Path("transcripts/raw/NVDA_Q1_2026.txt"), _synth_text("stockanalysis")
        )
        == "aggregator_stockanalysis"
    )
    assert (
        classify_transcript_source(
            Path("transcripts/raw/NVDA_Q1_2026.txt"), _synth_text("google_finance_beta")
        )
        == "aggregator_google_finance_beta"
    )


def test_classify_pdf_extension_is_manual_when_no_banner() -> None:
    assert (
        classify_transcript_source(
            Path("transcripts/processed/NVDA_Q1_2026.pdf"), "plain text body"
        )
        == MANUAL_PDF
    )


def test_classify_txt_with_no_banner_falls_back_to_index_hint() -> None:
    assert (
        classify_transcript_source(
            Path("transcripts/raw/NVDA_Q1_2026.txt"),
            "plain whisper transcript text",
            index_hint="yt_dlp_whisper_url",
        )
        == "yt_dlp_whisper_url"
    )


def test_classify_txt_with_no_banner_and_no_hint_is_unknown_legacy() -> None:
    assert (
        classify_transcript_source(Path("transcripts/raw/NVDA_Q1_2026.txt"), "plain text, no clues")
        == UNKNOWN_LEGACY
    )


def test_reliability_rank_ordering_matches_evidence() -> None:
    # Full-call/official sources outrank Q&A-only aggregators; roic,
    # stockanalysis, and tickertrends are all DOM-verified per-turn parses
    # as of 2026-07-25 (src/aggregator_sources.py) — equal tier, none still
    # on the old flatten-and-guess heuristic.
    assert reliability_rank(IR_TRANSCRIPT_DOC) > reliability_rank(MANUAL_PDF)
    assert reliability_rank(MANUAL_PDF) > reliability_rank("aggregator_google_finance_beta")
    assert reliability_rank("aggregator_google_finance_beta") == reliability_rank(
        "google_finance_beta"
    )
    assert reliability_rank("aggregator_google_finance_beta") > reliability_rank(
        "yt_dlp_whisper_url"
    )
    assert reliability_rank("yt_dlp_whisper_url") > reliability_rank("yt_dlp_whisper_search")
    assert reliability_rank("yt_dlp_whisper_search") > reliability_rank("aggregator_issuer_ir")
    assert reliability_rank("aggregator_issuer_ir") > reliability_rank("aggregator_roic")
    assert reliability_rank("aggregator_roic") == reliability_rank("aggregator_stockanalysis")
    assert reliability_rank("aggregator_stockanalysis") == reliability_rank(
        "aggregator_tickertrends"
    )
    assert reliability_rank("aggregator_tickertrends") > reliability_rank(UNKNOWN_LEGACY)
    assert reliability_rank(UNKNOWN_LEGACY) > reliability_rank("something_never_seen")
    assert reliability_rank(None) == reliability_rank("something_never_seen")


def test_choose_winner_higher_tier_wins_even_with_fewer_segments() -> None:
    """The GOOG Q1 2025 real-world case: a 7-segment manual PDF (full call,
    64k chars) must beat a 22-segment Q&A-only aggregator scrape."""
    assert choose_winner(
        new_source=MANUAL_PDF,
        new_segment_count=7,
        old_source="aggregator_roic",
        old_segment_count=22,
    )
    assert not choose_winner(
        new_source="aggregator_roic",
        new_segment_count=22,
        old_source=MANUAL_PDF,
        old_segment_count=7,
    )


def test_choose_winner_same_tier_falls_back_to_segment_count() -> None:
    assert choose_winner(
        new_source="aggregator_roic",
        new_segment_count=34,
        old_source="aggregator_roic",
        old_segment_count=1,
    )
    assert not choose_winner(
        new_source="aggregator_roic",
        new_segment_count=1,
        old_source="aggregator_roic",
        old_segment_count=34,
    )


def test_choose_winner_same_tier_same_segments_is_not_a_replace() -> None:
    """A strict '>' means a genuine tie never triggers churn."""
    assert not choose_winner(
        new_source="aggregator_roic",
        new_segment_count=10,
        old_source="aggregator_roic",
        old_segment_count=10,
    )


def test_choose_winner_treats_missing_old_source_as_unknown_legacy() -> None:
    assert choose_winner(
        new_source=MANUAL_PDF, new_segment_count=1, old_source=None, old_segment_count=100
    )


def test_choose_winner_google_finance_beta_beats_qa_only_and_whisper_below_manual_pdf() -> None:
    assert choose_winner(
        new_source="aggregator_google_finance_beta",
        new_segment_count=12,
        old_source="aggregator_roic",
        old_segment_count=40,
    )
    assert choose_winner(
        new_source="google_finance_beta",
        new_segment_count=12,
        old_source="yt_dlp_whisper_url",
        old_segment_count=40,
    )
    assert not choose_winner(
        new_source="aggregator_google_finance_beta",
        new_segment_count=50,
        old_source=MANUAL_PDF,
        old_segment_count=7,
    )


def test_qa_availability_rank_prioritizes_confirmed_qa_only() -> None:
    assert qa_availability_rank(True) == 1
    assert qa_availability_rank(1) == 1
    assert qa_availability_rank(False) == 0
    assert qa_availability_rank(0) == 0
    assert qa_availability_rank(None) == 0


def test_transcript_winner_key_orders_by_qa_then_tier_then_segments() -> None:
    qa_roic = transcript_winner_key(has_qa_section=True, source="aggregator_roic", segment_count=5)
    no_qa_ir = transcript_winner_key(
        has_qa_section=False, source=IR_TRANSCRIPT_DOC, segment_count=200
    )
    unknown_qa_ir = transcript_winner_key(
        has_qa_section=None, source=IR_TRANSCRIPT_DOC, segment_count=200
    )
    qa_ir = transcript_winner_key(has_qa_section=True, source=IR_TRANSCRIPT_DOC, segment_count=5)
    assert qa_roic > no_qa_ir
    assert qa_roic > unknown_qa_ir
    assert no_qa_ir == unknown_qa_ir
    assert qa_ir > qa_roic


def test_choose_winner_qa_beats_higher_source_tier_without_qa() -> None:
    """Owner policy: confirmed Q&A beats prepared-remarks-only / unknown IR & PDF rows."""
    for lower_source in ("aggregator_google_finance_beta", "aggregator_roic", UNKNOWN_LEGACY):
        for higher_source in (IR_TRANSCRIPT_DOC, MANUAL_PDF):
            for old_qa in (False, None):
                assert choose_winner(
                    new_source=lower_source,
                    new_segment_count=3,
                    new_has_qa=True,
                    old_source=higher_source,
                    old_segment_count=100,
                    old_has_qa=old_qa,
                )


def test_choose_winner_higher_tier_without_qa_never_replaces_lower_tier_with_qa() -> None:
    for higher_source in (IR_TRANSCRIPT_DOC, MANUAL_PDF):
        for new_qa in (False, None):
            assert not choose_winner(
                new_source=higher_source,
                new_segment_count=100,
                new_has_qa=new_qa,
                old_source="aggregator_roic",
                old_segment_count=3,
                old_has_qa=True,
            )


def test_choose_winner_equal_qa_availability_falls_back_to_source_tier_and_segments() -> None:
    # Both have confirmed Q&A -> higher source tier wins even with fewer segments.
    assert choose_winner(
        new_source=IR_TRANSCRIPT_DOC,
        new_segment_count=8,
        new_has_qa=True,
        old_source="aggregator_google_finance_beta",
        old_segment_count=60,
        old_has_qa=True,
    )
    assert not choose_winner(
        new_source="aggregator_google_finance_beta",
        new_segment_count=60,
        new_has_qa=True,
        old_source=IR_TRANSCRIPT_DOC,
        old_segment_count=8,
        old_has_qa=True,
    )
    # Both have confirmed Q&A and same tier -> richer segment count wins.
    assert choose_winner(
        new_source="aggregator_roic",
        new_segment_count=25,
        new_has_qa=True,
        old_source="aggregator_stockanalysis",
        old_segment_count=12,
        old_has_qa=True,
    )
    # Absent (False) and unknown (None) tie at Q&A rank 0 -> source tier decides.
    assert choose_winner(
        new_source=IR_TRANSCRIPT_DOC,
        new_segment_count=5,
        new_has_qa=False,
        old_source="aggregator_roic",
        old_segment_count=50,
        old_has_qa=None,
    )
    assert choose_winner(
        new_source=IR_TRANSCRIPT_DOC,
        new_segment_count=5,
        new_has_qa=None,
        old_source="aggregator_roic",
        old_segment_count=50,
        old_has_qa=False,
    )
